/**
 * dsh-md-notes browser half entry: registers the feature's locale namespace,
 * then wires the shared store into the three registered slots (sidebar entry,
 * assistant action, overlay host). Uses React.createElement (no JSX) so this
 * file stays a plain `.ts` entry; feature modules live under
 * `./features/<Name>/`.
 * @module dsh-md-notes/client
 */
import * as React from 'react';
import { createNotesUiStore } from "./features/store.js";
import { createBusyTracker } from "./features/busy.js";
import { en, zh } from "./features/locales/index.js";
import { NotesEntry } from "./features/NotesEntry/NotesEntry.js";
import { NoteAction } from "./features/NoteAction/NoteAction.js";
import { NotePicker } from "./features/NotePicker/NotePicker.js";
import { NotesManager } from "./features/NotesManager/NotesManager.js";
import { SettingsSection } from "./features/Settings/SettingsSection.js";
import { createNotesSource } from "./features/ContextSource/ContextSource.js";
export const inject = ['slots', 'locale'];
/** React hook: subscribe to the store via uSES, re-render on snapshot change. */
function useStore(store) {
    return React.useSyncExternalStore(store.subscribe, store.getSnapshot);
}
/** Overlay host: renders the manager or the picker based on store state. */
function NotesOverlay(props) {
    const s = useStore(props.store);
    if (s.managerOpen)
        return React.createElement(NotesManager, { store: props.store, tracker: props.tracker, t: props.t });
    if (s.picker) {
        return React.createElement(NotePicker, {
            questionText: s.picker.questionText,
            answerText: s.picker.answerText,
            sessionTitle: s.picker.sessionTitle,
            store: props.store,
            tracker: props.tracker,
            t: props.t,
        });
    }
    return null;
}
/**
 * Client plugin body: register the locale namespace, then the sidebar entry,
 * the notes manager overlay, and the assistant-message note action — all
 * sharing one NotesUiStore and the `md-notes` locale seat.
 * @param ctx - client cordis context.
 */
export function apply(ctx) {
    const store = createNotesUiStore();
    const tracker = createBusyTracker(store);
    const t = ctx.locale.bind('md-notes');
    ctx.effect(() => ctx.locale.register('md-notes', { zh, en }), 'dsh-md-notes: locale dicts');
    // Session title for the append section heading — read from the client-side
    // sessions list (in-memory, no host round-trip), see docs/context.md.
    const getSessionTitle = (sessionId) => {
        const sessions = ctx.get('sessions');
        return sessions?.list?.getSnapshot().byId?.[sessionId]?.title ?? '';
    };
    // '@' reference source: notes as conversation context (docs/context.md).
    // Registered under ctx.effect so HMR/unmount clears the per-session caches.
    // The re-track hook re-opens the candidate menu right after a workspace
    // auto-complete (machine-driven draft changes never pass through onChange).
    const notesSource = createNotesSource(t, (sessionId, caret) => {
        const sessions = ctx.get('sessions');
        const actx = sessions?.scope(sessionId);
        if (actx === undefined)
            return;
        const conversation = actx.get('conversation');
        const input = conversation?.input?.for(actx);
        if (input === undefined)
            return;
        queueMicrotask(() => {
            input.track(input.snapshot.draft, caret);
        });
    });
    ctx.effect(() => {
        const inputTriggers = ctx.get('inputTriggers');
        if (inputTriggers === undefined) {
            // ui-input-trigger absent (unbundled host) — the feature is inert.
            console.warn('[dsh-md-notes] inputTriggers unavailable; @ reference disabled');
            return () => { };
        }
        const unregister = inputTriggers.registerSource(notesSource.source);
        return () => {
            unregister();
            notesSource.dispose();
        };
    }, 'dsh-md-notes: @ source');
    ctx.effect(() => ctx.slots.inject('sidebar.footer.action', () => ctx.slots.register({ name: 'sidebar.footer.action', id: 'dsh-notes-entry', order: 30, label: t('sidebar.label'), locale: 'md-notes' }, (props) => React.createElement(NotesEntry, { wide: props.wide, store, t: props.t }))), 'dsh-md-notes: sidebar entry');
    ctx.effect(() => ctx.slots.inject('conversation.chat.assistant-actions', () => ctx.slots.register({ name: 'conversation.chat.assistant-actions', id: 'dsh-notes-save', order: 20, label: t('action.tooltip'), locale: 'md-notes' }, (props) => React.createElement(NoteAction, {
        sessionId: String(props.sessionId),
        messageId: props.messageId,
        useSession: props.useSession,
        getSessionTitle,
        store,
        t: props.t,
    }))), 'dsh-md-notes: assistant action');
    ctx.effect(() => ctx.slots.inject('shell.overlay', () => ctx.slots.register({ name: 'shell.overlay', id: 'dsh-notes-overlay', order: 100, label: t('sidebar.entry'), locale: 'md-notes' }, (props) => React.createElement(NotesOverlay, { store, tracker, t: props.t }))), 'dsh-md-notes: overlay');
    ctx.effect(() => ctx.slots.inject('settings.section', () => ctx.slots.register({ name: 'settings.section', id: 'md-notes', order: 10, label: () => t('git.settingsNav'), locale: 'md-notes' }, SettingsSection)), 'dsh-md-notes: settings section');
}
